"use client"

import { useEffect, useRef, useState } from "react"
import { useMap } from "./hooks"
import type { MapPath } from "./types"

type MapCameraFollowProps = {
  path: MapPath
  duration?: number
  zoom?: number
  pitch?: number
  autoStart?: boolean
  loop?: boolean
  loopDelay?: number
  onComplete?: () => void
}

const DEFAULT_DURATION = 20000
const DEFAULT_ZOOM = 14
const DEFAULT_PITCH = 60
const DEFAULT_AUTO_START = true
const DEFAULT_LOOP = false
const DEFAULT_LOOP_DELAY = 1000

const calculateBearing = (from: [number, number], to: [number, number]): number => {
  const dLon = ((to[0] - from[0]) * Math.PI) / 180
  const lat1 = (from[1] * Math.PI) / 180
  const lat2 = (to[1] * Math.PI) / 180

  const y = Math.sin(dLon) * Math.cos(lat2)
  const x = Math.cos(lat1) * Math.sin(lat2) - Math.sin(lat1) * Math.cos(lat2) * Math.cos(dLon)

  return ((Math.atan2(y, x) * 180) / Math.PI + 360) % 360
}

export const MapCameraFollow = ({
  path,
  duration = DEFAULT_DURATION,
  zoom = DEFAULT_ZOOM,
  pitch = DEFAULT_PITCH,
  autoStart = DEFAULT_AUTO_START,
  loop = DEFAULT_LOOP,
  loopDelay = DEFAULT_LOOP_DELAY,
  onComplete,
}: MapCameraFollowProps) => {
  const { map, isLoaded } = useMap()

  const animationFrameRef = useRef<number | undefined>(undefined)
  const loopTimeoutRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const startTimeRef = useRef<number>(0)

  const pathRef = useRef(path)
  const durationRef = useRef(duration)
  const zoomRef = useRef(zoom)
  const pitchRef = useRef(pitch)
  const onCompleteRef = useRef(onComplete)
  const autoStartRef = useRef(autoStart)

  pathRef.current = path
  durationRef.current = duration
  zoomRef.current = zoom
  pitchRef.current = pitch
  onCompleteRef.current = onComplete
  autoStartRef.current = autoStart

  const [isAnimating, setIsAnimating] = useState(false)

  useEffect(() => {
    if (!map || !isLoaded) {
      return
    }
    if (!autoStart && !isAnimating) {
      return
    }
    if (pathRef.current.length < 2) {
      return
    }

    startTimeRef.current = Date.now()

    const interpolatePosition = (progress: number): [number, number] => {
      const route = pathRef.current
      const totalSegments = route.length - 1
      const segmentProgress = progress * totalSegments
      const segmentIndex = Math.min(Math.floor(segmentProgress), totalSegments - 1)
      const segmentFraction = segmentProgress - segmentIndex

      const start = route[segmentIndex]
      const end = route[segmentIndex + 1]

      return [
        start[0] + (end[0] - start[0]) * segmentFraction,
        start[1] + (end[1] - start[1]) * segmentFraction,
      ]
    }

    const stopAnimation = () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current)
        animationFrameRef.current = undefined
      }
      setIsAnimating(false)
    }

    const animate = () => {
      if (!map) {
        stopAnimation()
        return
      }

      const elapsed = Date.now() - startTimeRef.current
      const progress = Math.min(elapsed / durationRef.current, 1)

      const currentPosition = interpolatePosition(progress)
      const lookAheadProgress = Math.min(progress + 0.02, 1)
      const lookAheadPosition = interpolatePosition(lookAheadProgress)
      const bearing = calculateBearing(currentPosition, lookAheadPosition)

      try {
        map.easeTo({
          center: currentPosition,
          bearing,
          pitch: pitchRef.current,
          zoom: zoomRef.current,
          duration: 0,
        })
      } catch {
        stopAnimation()
        return
      }

      if (progress < 1) {
        animationFrameRef.current = requestAnimationFrame(animate)
        return
      }

      setIsAnimating(false)
      onCompleteRef.current?.()

      if (loop) {
        loopTimeoutRef.current = setTimeout(() => {
          setIsAnimating(true)
        }, loopDelay)
      }
    }

    setIsAnimating(true)
    animationFrameRef.current = requestAnimationFrame(animate)

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current)
      }
      if (loopTimeoutRef.current) {
        clearTimeout(loopTimeoutRef.current)
      }
    }
  }, [map, isLoaded, autoStart, loop, loopDelay, isAnimating])

  return null
}

export const useCameraFollowControl = () => {
  const [isPlaying, setIsPlaying] = useState(false)

  const start = () => {
    setIsPlaying(true)
  }

  const stop = () => {
    setIsPlaying(false)
  }

  const toggle = () => {
    setIsPlaying((prev) => {
      return !prev
    })
  }

  return {
    isPlaying,
    start,
    stop,
    toggle,
  }
}
